-- ==========================================================================
-- B4 FOLLOW-ON FIX (porepressure): porepressure: one duplicate rewrite
--
-- Courses: porepressure. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/porepressure.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql porepressure. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- porepressure advanced final - ord 14
  select case when md5(prompt) = '6ba904a6a3133affe97cc313845eb0a1' and md5(coalesce(explanation, '')) = '25e236e53c4ac1edebe7704a75840cad' and md5(options::text) = md5('["Narrows below the onset exactly as at n 3, from the same 750.28 maximum.", "Widens with depth below the onset: 750.28, 761.16, 782.97.", "Becomes exactly flat.", "Inverts outright, with the floor crossing above the ceiling at the deepest samples of the well."]'::jsonb::text) and answer_index = 1 then 'old'
              when md5(prompt) = '2e2c208bbe28e394c0195d0e8e9e3698' and md5(coalesce(explanation, '')) = '410728cc87a9b35212c312294dc2fbca' and md5(options::text) = md5('["Drops the same 87.22 kg/m3, so the window keeps its width at TD.", "Drops 29.07 kg/m3, a third of the floor move.", "Stays put at 1903.92.", "Rises 58.15 kg/m3, since the window widens by that amount while the floor falls beneath it."]'::jsonb::text) and answer_index = 1 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'porepressure' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 14 and active;
  if v_state is null then raise exception 'B4 fix porepressure refused: no row for porepressure advanced final - ord 14'; end if;
  if v_state = 'other' then raise exception 'B4 fix porepressure refused: porepressure advanced final - ord 14 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Under the n 1.2 calibration the TD floor drops 87.22 kg/m3. What does the fracture ceiling do there?', options = '["Drops the same 87.22 kg/m3, so the window keeps its width at TD.", "Drops 29.07 kg/m3, a third of the floor move.", "Stays put at 1903.92.", "Rises 58.15 kg/m3, since the window widens by that amount while the floor falls beneath it."]'::jsonb,
           answer_index = 1, explanation = 'The ceiling moves only through the mixture, a third of the floor''s change: 1903.92 to 1874.85 kg/m3 at TD, a drop of 29.07 for the floor''s 87.22. The window therefore widens by the other two thirds, 58.15 kg/m3, with both walls moving down.'
     where app_slug = 'porepressure' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 14 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix porepressure refused: porepressure advanced final - ord 14 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'porepressure' and active;
  if v_total <> 396 then raise exception 'B4 fix porepressure refused: porepressure holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix porepressure: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
